import { createSolrahnV2 } from './solrahn-v2';
import type { SolrahnMetadata } from './solrahn-v2';

// Crownfall Coliseum (founder-approved single-lane arena). Generated by scripts/coliseum/build-coliseum.py
// in the same format as Sol'Rahn V2, so movement, bots, scoring and camera use it unchanged.
export async function loadColiseum() {
    const base = `${import.meta.env.BASE_URL}assets/coliseum/`;
    const response = await fetch(`${base}terrain.json`);
    if (!response.ok) throw new Error(`Coliseum terrain.json: HTTP ${response.status}`);
    const meta = (await response.json()) as SolrahnMetadata & {
        files: Record<string, { bytes: number; sha256: string }>;
    };
    const buffers = await Promise.all(
        ['height.u16', 'walk.bin', 'lane.bin', 'colors.bin'].map(async (name) => {
            const r = await fetch(`${base}${name}`);
            if (!r.ok) throw new Error(`Coliseum ${name}: HTTP ${r.status}`);
            const buffer = await r.arrayBuffer();
            const spec = meta.files[name];
            if (!spec || buffer.byteLength !== spec.bytes) throw new Error(`Coliseum ${name}: incomplete data`);
            const digest = await crypto.subtle.digest('SHA-256', buffer);
            if (Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, '0')).join('') !== spec.sha256)
                throw new Error(`Coliseum ${name}: checksum mismatch`);
            return buffer;
        })
    );
    return createSolrahnV2(buffers[0], buffers[1], buffers[2], meta, buffers[3]);
}
